SET NAMES utf8mb4;
-- Guide per le restanti pagine della dashboard (il "?" compare ora su tutte). Si può rieseguire: non sovrascrive i testi già presenti.
INSERT IGNORE INTO page_help (page_key, title, body, more, sort_order) VALUES
('dashboard_timeline', 'Feed', 'Il Feed raccoglie in un unico elenco tutto ciò che compare sul tuo profilo e sui profili che segui: articoli, aggiornamenti, brani, foto, video ed eventi.', 'Usa **Filtri** per scegliere cosa vedere (tipo di contenuto, solo i tuoi o solo quelli dei profili seguiti) e il selettore **Lista / Card** per cambiare la vista. Ogni elemento si apre con un clic.

I contenuti «Solo io» o programmati compaiono nel Feed solo quando sono pubblici.', 1010),
('dashboard_profile', 'Profilo', 'Qui modifichi come ti presenti: nome, descrizione, foto profilo, colore e informazioni di contatto. Sono i dati che vedono i visitatori della tua pagina pubblica.', 'Il colore scelto qui resta il tuo accento personale anche cambiando tema grafico. In fondo alla pagina trovi l''eliminazione dell''account.', 1020),
('dashboard_events', 'Eventi', 'Aggiungi qui i tuoi eventi con data, luogo, descrizione e link ai biglietti. Compaiono nella sezione pubblica «Eventi» e sulla mappa del tuo profilo.', 'Con provincia, locale e città l''evento viene raggruppato nel riquadro «Eventi per provincia» e posizionato sulla mappa (usa **Calcola le posizioni** per gli eventi senza coordinate).

Puoi programmare la pubblicazione per una data futura e farti aiutare dall''AI per la descrizione.', 1030),
('dashboard_featured', 'Primo Piano', 'Scegli quali contenuti mettere in evidenza in cima alla tua pagina pubblica, in un carosello. Cerca un contenuto e fissalo.', 'Serve almeno un secondo elemento perché il carosello compaia. Con le frecce decidi l''ordine; togliendo il segno un contenuto torna normale.', 1040),
('dashboard_contacts', 'Contatti', 'Qui arrivano i messaggi inviati dal modulo «Contatti» del tuo profilo. Puoi leggerli, segnarli come letti e rispondere.', 'Quando rispondi, l''utente riceve la tua risposta per email e la conversazione resta conservata qui. I messaggi non letti sono contati nella campanella in alto.', 1050),
('dashboard_service_inquiries', 'Richieste sui servizi', 'Le richieste di informazioni inviate dai visitatori sui tuoi servizi: le vedi qui e ti arrivano anche per email.', 'Il pulsante «Richiedi informazioni» si attiva o disattiva per ogni servizio dalla pagina Servizi.', 1060),
('dashboard_blog_posts', 'Articoli del blog', 'L''elenco completo dei tuoi articoli: cerca per testo o categoria, modifica, elimina o metti in coda sui social quelli già pubblicati.', 'Un articolo programmato resta visibile solo a te fino alla data scelta. I badge indicano se è in coda social e chi lo ha scritto.', 1070),
('dashboard_blog_edit', 'Modifica articolo', 'Modifica testo, immagine, categorie, tag e data di pubblicazione dell''articolo. Le modifiche valgono subito per i lettori.', 'Puoi scegliere Pubblico o Solo io, programmare la pubblicazione e, in fondo alla pagina, eliminare l''articolo (operazione definitiva).', 1080),
('dashboard_blog_categories', 'Categorie del blog', 'Organizza gli articoli in categorie: crea, rinomina o elimina le categorie. Le categorie compaiono nella pagina pubblica del blog come filtro.', NULL, 1090),
('dashboard_timeline_edit', 'Modifica aggiornamento', 'Modifica il testo, le foto e le impostazioni di un aggiornamento della Timeline già creato.', 'Puoi cambiare tra Pubblico e Solo io, programmare la data di pubblicazione e, in fondo alla pagina, eliminarlo.', 1100),
('dashboard_chat', 'Messaggi', 'La conversazione privata con un altro profilo. Scrivi nel campo in basso e premi Invia.', 'Il messaggio compare subito all''altro utente, che riceve un avviso se non è collegato.', 1110),
('dashboard_privacy_tracking', 'Privacy e Tracking', 'Imposta cookie, privacy policy e strumenti di statistica (Google Analytics, Tag Manager, Meta Pixel) per la tua pagina pubblica.', 'Incolla gli script che ti fornisce il tuo servizio di consenso cookie e inserisci l''indirizzo della tua informativa privacy: comparirà nel piè di pagina. Gli strumenti di tracciamento partono solo dopo il consenso del visitatore.', 1120),
('dashboard_password', 'Cambia password', 'Cambia la password del tuo account: inserisci quella attuale e poi quella nuova.', 'Scegli una password lunga e diversa da quelle che usi altrove. Se l''hai dimenticata, usa «Password dimenticata» nella pagina di accesso.', 1130),
('dashboard_delete_account', 'Elimina il mio account', 'Cancella in modo definitivo il tuo account e tutti i contenuti, immagini, video e brani collegati. Per confermare scrivi la parola Elimina.', 'L''operazione è immediata e non si può annullare. Riceverai un''email di conferma. I profili che hai creato vengono eliminati insieme all''account; quelli che gestisci solo come co-amministratore non vengono toccati.', 1140),
('dashboard_social_queue', 'Coda Social', 'L''elenco dei contenuti in coda per la pubblicazione sui social: vedi cosa è in attesa, in elaborazione, programmato, pubblicato o in errore.', 'Con **Filtri** scegli stato e tipo. Un clic sulle immagini o sui video mostra l''anteprima di ciò che verrà pubblicato. Da qui puoi sospendere, riprendere o rimuovere un elemento.', 1150),
('dashboard_schedule_admin', 'Calendario Programmazioni', 'Il calendario di tutto ciò che è programmato per essere pubblicato, con filtro per account.', 'Serve agli amministratori per avere sotto controllo le pubblicazioni future di più profili.', 1160),
('dashboard_api_tokens', 'API', 'Crea e gestisci i token che permettono a strumenti esterni (script, assistenti AI) di pubblicare e leggere contenuti a nome del profilo.', 'Il token si vede una sola volta: copialo subito, perché dopo non potrai più rivederlo. Se lo perdi, creane uno nuovo e revoca il vecchio. Ogni richiesta va autenticata con l''header `Authorization: Bearer IL_TUO_TOKEN`; il limite è 100 richieste all''ora per token.', 1170),
('dashboard_marketing', 'Marketing', 'Progetti di marketing pianificati a passi, che puoi far eseguire a un assistente AI.', 'Il dettaglio è nel popup ❓ accanto al titolo della pagina.', 1180);
